    let fib = Fib::parse(&word)?;
    let table = file
        .stream(if fib.table_one { "1Table" } else { "0Table" })
        .ok_or_else(|| LegacyDocError::new("the table stream the FIB names is missing"))?;
    let pieces = pieces(&table, fib.fc_clx, fib.lcb_clx)?;
    let chars = main_text(&word, &pieces, fib.ccp_text)?;

fn drop_repeated_relationships(rels: &mut Relationships) -> Result<Vec<String>, OpcError> {
    let mut seen: HashMap<&str, &Relationship> = HashMap::new();
    let mut repaired: Vec<String> = Vec::new();
    let mut keep = Vec::with_capacity(rels.items.len());
    for item in &rels.items {
        match seen.get(item.id.as_str()) {
            None => {
                seen.insert(&item.id, item);
                keep.push(true);
            }
            Some(first) => {
                if first.rel_type != item.rel_type
                    || first.target != item.target
                    || first.target_mode != item.target_mode
                {
                    return Err(OpcError::InvalidRelationship);
                }
                if !repaired.contains(&item.id) {
                    repaired.push(item.id.clone());
                }
                keep.push(false);
            }
        }
    }
    let mut keep = keep.into_iter();
    rels.items.retain(|_| keep.next().unwrap_or(true));
    Ok(repaired)

let mut fs = read_package(bytes, limits)?;
let mut repaired_duplicate_ids: Vec<(String, String)> =
    drop_repeated_relationships(&mut fs.package_rels)?
        .into_iter()
        .map(|id| (String::new(), id))
        .collect();
let mut owners: Vec<&String> = fs.part_rels.keys().collect();
owners.sort();
let owners: Vec<String> = owners.into_iter().cloned().collect();
for owner in owners {
    if let Some(rels) = fs.part_rels.get_mut(&owner) {
        let part = owner.trim_start_matches('/').to_string();
        repaired_duplicate_ids.extend(
            drop_repeated_relationships(rels)?
                .into_iter()
                .map(|id| (part.clone(), id)),
        );
    }

let floor = bytes.len().saturating_sub(22 + usize::from(u16::MAX));
let at = (floor..=bytes.len().saturating_sub(22))
    .rev()
    .find(|&i| bytes.get(i..).is_some_and(|tail| tail.starts_with(&EOCD)))
    .ok_or_else(|| invalid("no end-of-central-directory record"))?;
let total = bytes
    .get(at.saturating_add(10)..at.saturating_add(12))
    .and_then(|field| <[u8; 2]>::try_from(field).ok())
    .map(u16::from_le_bytes)
    .ok_or_else(|| invalid("truncated end-of-central-directory record"))?;
if total != u16::MAX {
    return Ok(u64::from(total));
}

pub(crate) fn preindex_budget(bytes: &[u8], limits: InputLimits) -> Result<u64, AdmissionError> {
    if bytes.len() as u64 > limits.max_compressed_bytes {
        return Err(input_over_compressed(bytes.len() as u64, &limits));
    }
    let declared = declared_entry_count(bytes)?;
    if declared > limits.max_entries as u64 {
        return Err(input_over_entries(declared, &limits));
    }
    Ok(declared)

let declared = preindex_budget(bytes, limits)?;
// The shared open (`crate::opc::open_archive`) runs this same check, but
// as a plain zip error; admission opens unchecked so the refusal keeps
// its typed kind.
let mut archive = crate::opc::open_archive_unchecked(Cursor::new(bytes))
    .map_err(|e| AdmissionError::new(K::InvalidPackage, format!("not a ZIP file: {e}")))?;
// The reader keys entries by name, so exact duplicates collapse into one.
if (archive.len() as u64) < declared {
    return Err(AdmissionError::new(
        K::DuplicatePart,
        "two ZIP entries have the same name",
    ));
}
